mapper.insert:
INSERT INTO uav_operate_log (
    station_id, device_type, cmd_type, cmd_name,
    cmd_param, result, operate_time
) VALUES (
    #{stationId}, #{deviceType}, #{cmdType}, #{cmdName},
    #{cmdParam}, #{result}, #{operateTime}
)

mapper.select:
SELECT * FROM uav_operate_log
WHERE cmd_type = #{cmdType}
  AND station_id = #{stationId}
ORDER BY operate_time DESC
LIMIT #{limit}

SELECT * FROM uav_operate_log
WHERE result = #{result}
  AND device_type = #{deviceType}
  AND operate_time BETWEEN #{startTime} AND #{endTime}
ORDER BY operate_time DESC
